//go:build linux && !tinygo

package riscv64

import (
	"crypto/sha256"

	"github.com/wago-org/wago/src/core/compiler/wasm"
)

const rv64GCBrOnCastConcreteHex = ""

const rv64GCBrOnCastFailConcreteHex = ""

var (
	rv64GCBrOnCastConcreteSourceDigest     = [sha256.Size]byte{0x4e, 0xab, 0xad, 0xd9, 0x8e, 0x55, 0xbc, 0x0c, 0x83, 0x60, 0x0f, 0x07, 0x2a, 0x16, 0xba, 0xb7, 0x5e, 0x3d, 0x74, 0x17, 0x0d, 0x2f, 0x24, 0xbb, 0x6b, 0xda, 0xe4, 0xac, 0xf0, 0xb5, 0x49, 0x1b}
	rv64GCBrOnCastFailConcreteSourceDigest = [sha256.Size]byte{0x88, 0x89, 0x41, 0x27, 0xfa, 0xbe, 0x14, 0xa4, 0x2d, 0xc6, 0xd5, 0xaf, 0x44, 0x02, 0x73, 0x18, 0x07, 0x8b, 0x70, 0x2b, 0xcc, 0x67, 0xfc, 0x34, 0xe7, 0x52, 0xd1, 0x45, 0xa8, 0x16, 0x43, 0x12}
)

func admitRV64GCBrOnCastConcreteWireKind(data []byte, fail bool) bool {
	wantLen, wantDigest := 772, rv64GCBrOnCastConcreteSourceDigest
	if fail {
		wantLen, wantDigest = 876, rv64GCBrOnCastFailConcreteSourceDigest
	}
	if len(data) != wantLen || sha256.Sum256(data) != wantDigest {
		return false
	}
	m, err := wasm.DecodeModule(data)
	return err == nil && admitRV64GCBrOnCastConcreteKind(m, fail)
}

func admitRV64GCBrOnCastConcreteKind(m *wasm.Module, fail bool) bool {
	if !admitRV64GCRefTestConcreteShape(m) {
		return false
	}
	wantLengths := []int{57, 358, 204}
	wantDigests := [][sha256.Size]byte{
		{0x6f, 0x4c, 0x93, 0xa6, 0x4d, 0xcf, 0x4f, 0x85, 0xe3, 0x27, 0x1e, 0x81, 0x13, 0x6e, 0x62, 0xd7, 0x83, 0xf8, 0x3d, 0x61, 0x86, 0x74, 0xc9, 0x0d, 0x2b, 0xda, 0x3a, 0xe8, 0xe1, 0x64, 0x37, 0x74},
		{0xaf, 0x8a, 0xc5, 0xb1, 0xdd, 0x87, 0x82, 0xf9, 0xc7, 0xd2, 0x1c, 0xf9, 0x7e, 0xad, 0x2e, 0x10, 0x04, 0x90, 0xb5, 0x98, 0x5c, 0x9a, 0xf9, 0x9a, 0x81, 0x0b, 0xb6, 0x6b, 0xd5, 0x08, 0x36, 0x7a},
		{0x1e, 0x63, 0xe6, 0x6a, 0x27, 0xfc, 0x61, 0x6b, 0x58, 0x98, 0x12, 0x9a, 0x48, 0x13, 0x30, 0xc1, 0x17, 0x81, 0xe1, 0x02, 0x69, 0x22, 0x0d, 0x42, 0xf1, 0x0b, 0xe5, 0x24, 0xff, 0x07, 0xec, 0xf0},
	}
	if fail {
		wantLengths = []int{57, 518, 148}
		wantDigests = [][sha256.Size]byte{
			{0xcf, 0x5f, 0xee, 0x10, 0x76, 0xc5, 0xf8, 0xf6, 0x83, 0x75, 0x06, 0x7c, 0x7b, 0x04, 0xf7, 0xf0, 0x75, 0x28, 0x8f, 0xa2, 0x7d, 0x25, 0x9a, 0x79, 0x28, 0x6a, 0x60, 0x75, 0x21, 0xde, 0x8a, 0x4f},
			{0xd5, 0xd4, 0xe2, 0x4f, 0xbe, 0x51, 0x52, 0xf7, 0x21, 0x11, 0xe3, 0x46, 0xf4, 0x86, 0x11, 0x41, 0x24, 0x56, 0x07, 0x03, 0x60, 0x29, 0x49, 0x13, 0x18, 0x86, 0x13, 0xc2, 0x75, 0xdd, 0xbb, 0x9a},
			{0x3b, 0x90, 0x8d, 0x30, 0x11, 0x7c, 0xd2, 0x58, 0xe5, 0x1e, 0xfb, 0x85, 0xed, 0xb4, 0x06, 0x96, 0x1b, 0x19, 0xc8, 0xfa, 0x4a, 0xe1, 0xae, 0x06, 0x75, 0xb1, 0xd1, 0xd2, 0xfc, 0xbc, 0x46, 0xd8},
		}
	}
	for i := range m.Code {
		if len(m.Code[i].BodyBytes) != wantLengths[i] || sha256.Sum256(m.Code[i].BodyBytes) != wantDigests[i] {
			return false
		}
	}
	return true
}
